import { loadFont as loadArchivo } from "@remotion/google-fonts/Archivo";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// AÇORON FERRO E AÇO (Porto Velho) · "Moço, me vê um ferro aí". Recriação do vídeo de 37 s com o mesmo áudio
// (diálogo + locução já mixados, tirados do vídeo antigo). Pedido: a parte dos tipos de ferro mais visual e clean.
// Identidade: escudo AR em azul (royal + ciano), marinho do nome, Archivo pesada. Os 6 tipos são desenhados em 3D
// (perfil extrudado em camadas), um por palavra da fala; fotos do Pexels só nas cenas de obra.
// Tempos = tempo da palavra no áudio (Movies/acorou/src/transcricao.json).

const { fontFamily: F } = loadArchivo("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const AC_FPS = 30;
export const AC_FRAMES = Math.round(37.07 * AC_FPS);

const BG = "#EFF3F8";
const INK = "#111A36";
const NAVY = "#0E2466";
const ROYAL = "#1D4FB8";
const CYAN = "#14A3E6";
const RED = "#E5484D";
const GREEN = "#1DB36B";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const sp = (t: number, a: number, damping = 18, stiffness = 140) =>
  spring({ frame: Math.round((t - a) * AC_FPS), fps: AC_FPS, config: { damping, stiffness } });

// ───────── texto: palavra nasce de baixo da linha (máscara) e fica parada ─────────
type W = [string, number, boolean?];
const Line: React.FC<{ t: number; words: W[]; size: number; color?: string; hi?: string; weight?: number }> = ({ t, words, size, color = INK, hi = ROYAL, weight = 800 }) => (
  <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: size * 0.26, fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.12, letterSpacing: -0.5 }}>
    {words.map(([w, at, h], i) => {
      const p = sp(t, at, 20, 170);
      return (
        <span key={i} style={{ display: "inline-block", overflow: "hidden", paddingBottom: size * 0.08 }}>
          <span style={{ display: "inline-block", transform: `translateY(${(1 - p) * 110}%)`, color: h ? hi : color }}>{w}</span>
        </span>
      );
    })}
  </div>
);

// ───────── balão de conversa ─────────
const Avatar: React.FC<{ loja?: boolean }> = ({ loja }) =>
  loja ? (
    <div style={{ width: 92, height: 92, borderRadius: 46, background: WHITE, boxShadow: "0 6px 18px rgba(14,36,102,0.18)", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <Img src={staticFile("acorou/logo-ar.png")} style={{ width: 62 }} />
    </div>
  ) : (
    <div style={{ width: 92, height: 92, borderRadius: 46, background: "#C9D3E2", overflow: "hidden", position: "relative" }}>
      <div style={{ position: "absolute", left: 30, top: 18, width: 32, height: 32, borderRadius: 16, background: "#7F8EA6" }} />
      <div style={{ position: "absolute", left: 16, top: 56, width: 60, height: 50, borderRadius: 30, background: "#7F8EA6" }} />
    </div>
  );

const Bubble: React.FC<{ t: number; at: number; who: string; loja?: boolean; children: React.ReactNode; width?: number }> = ({ t, at, who, loja, children, width = 840 }) => {
  const p = sp(t, at, 16, 160);
  return (
    <div style={{ width, transform: `translateY(${(1 - p) * 60}px) scale(${0.9 + 0.1 * p})`, opacity: interpolate(p, [0, 0.35], [0, 1], cl), transformOrigin: loja ? "100% 100%" : "0% 100%" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 18, marginBottom: 18, flexDirection: loja ? "row-reverse" : "row" }}>
        <Avatar loja={loja} />
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: 30, letterSpacing: 3, color: loja ? ROYAL : "#6B7891", textTransform: "uppercase" }}>{who}</div>
      </div>
      <div
        style={{
          background: loja ? WHITE : NAVY,
          color: loja ? INK : WHITE,
          borderRadius: 44,
          borderTopLeftRadius: loja ? 44 : 10,
          borderTopRightRadius: loja ? 10 : 44,
          padding: "44px 52px",
          boxShadow: "0 24px 60px rgba(14,36,102,0.16)",
        }}
      >
        {children}
      </div>
    </div>
  );
};

// ───────── perfis de ferro em 3D: o corte é empilhado em camadas ao longo do comprimento ─────────
type Perfil = { nome: string; d: string; comp: number };
const PERFIS: Perfil[] = [
  { nome: "Barra", d: "M120 52a68 68 0 1 0 0.01 0Z", comp: 760 },
  { nome: "Metalon", d: "M44 44H196V196H44Z M62 62V178H178V62Z", comp: 720 },
  { nome: "Cantoneira", d: "M48 40H74V170H204V196H48Z", comp: 720 },
  { nome: "Perfil C", d: "M60 36H196V88H174V60H86V180H174V152H196V204H60Z", comp: 720 },
  { nome: "Tubo", d: "M120 40a80 80 0 1 0 0.01 0Z M120 58a62 62 0 1 1 -0.01 0Z", comp: 760 },
  { nome: "Chapa", d: "M10 110H230V126H10Z", comp: 520 },
];

const Extrude: React.FC<{ d: string; comp: number; size: number; rotY: number; rotX: number; layers?: number; glow?: number }> = ({ d, comp, size, rotY, rotX, layers = 56, glow = 0 }) => {
  const id = React.useId().replace(/:/g, "");
  return (
    <div style={{ width: size, height: size, perspective: 2400 }}>
      <div style={{ width: size, height: size, position: "relative", transformStyle: "preserve-3d", transform: `rotateX(${rotX}deg) rotateY(${rotY}deg)` }}>
        {Array.from({ length: layers + 1 }).map((_, i) => {
          const z = -comp / 2 + (i / layers) * comp;
          const front = i === layers;
          const shade = Math.round(interpolate(i, [0, layers], [70, 140]));
          return (
            <svg key={i} viewBox="0 0 240 240" width={size} height={size} style={{ position: "absolute", inset: 0, transform: `translateZ(${z}px)` }}>
              {front && (
                <defs>
                  <linearGradient id={`g${id}`} x1="0" y1="0" x2="1" y2="1">
                    <stop offset="0" stopColor="#F4F7FB" />
                    <stop offset="0.55" stopColor="#BAC6D6" />
                    <stop offset="1" stopColor="#8796AD" />
                  </linearGradient>
                </defs>
              )}
              <path
                d={d}
                fillRule="evenodd"
                fill={front ? `url(#g${id})` : `rgb(${shade - 10},${shade + 4},${shade + 26})`}
                stroke={front ? (glow > 0 ? CYAN : "rgba(255,255,255,0.9)") : "none"}
                strokeWidth={front ? 1.6 + glow * 3 : 0}
              />
            </svg>
          );
        })}
      </div>
    </div>
  );
};

// ───────── ícones ─────────
const Regua: React.FC<{ s?: number; c?: string }> = ({ s = 64, c = ROYAL }) => (
  <svg width={s} height={s} viewBox="0 0 64 64">
    <rect x="4" y="20" width="56" height="24" rx="4" fill="none" stroke={c} strokeWidth="5" />
    {[14, 24, 34, 44].map((x, i) => <line key={x} x1={x} y1="20" x2={x} y2={i % 2 ? 30 : 34} stroke={c} strokeWidth="4" />)}
  </svg>
);
const Capacete: React.FC<{ s?: number; c?: string }> = ({ s = 64, c = ROYAL }) => (
  <svg width={s} height={s} viewBox="0 0 64 64">
    <path d="M12 44 Q12 16 32 16 Q52 16 52 44 Z" fill="none" stroke={c} strokeWidth="5" strokeLinejoin="round" />
    <line x1="6" y1="46" x2="58" y2="46" stroke={c} strokeWidth="6" strokeLinecap="round" />
    <line x1="32" y1="16" x2="32" y2="30" stroke={c} strokeWidth="5" />
  </svg>
);
const Marca: React.FC<{ p: number; ok: boolean }> = ({ p, ok }) => (
  <div style={{ width: 84, height: 84, borderRadius: 42, background: ok ? GREEN : RED, transform: `scale(${p})`, display: "flex", alignItems: "center", justifyContent: "center" }}>
    <svg width="46" height="46" viewBox="0 0 46 46">
      {ok ? (
        <path d="M9 24 L19 34 L37 13" fill="none" stroke={WHITE} strokeWidth="7" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="50" strokeDashoffset={50 * (1 - p)} />
      ) : (
        <g stroke={WHITE} strokeWidth="7" strokeLinecap="round">
          <line x1="12" y1="12" x2="34" y2="34" />
          <line x1="34" y1="12" x2="12" y2="34" />
        </g>
      )}
    </svg>
  </div>
);

// ───────── transição: a cena nova entra por um círculo que inunda a tela ─────────
const Flood: React.FC<{ t: number; a: number; x?: number; y?: number; d?: number; children: React.ReactNode }> = ({ t, a, x = 50, y = 50, d = 0.5, children }) => {
  if (t < a) return null;
  const r = interpolate(t, [a, a + d], [0, 150], { ...cl, easing: Easing.bezier(0.55, 0, 0.25, 1) });
  return <AbsoluteFill style={{ clipPath: r >= 150 ? undefined : `circle(${r}% at ${x}% ${y}%)` }}>{children}</AbsoluteFill>;
};
// a cena nova sobe de baixo, a anterior fica embaixo
const Rise: React.FC<{ t: number; a: number; d?: number; children: React.ReactNode }> = ({ t, a, d = 0.5, children }) => {
  if (t < a) return null;
  const y = interpolate(t, [a, a + d], [100, 0], { ...cl, easing: Easing.bezier(0.6, 0, 0.2, 1) });
  return <AbsoluteFill style={{ transform: `translateY(${y}%)` }}>{children}</AbsoluteFill>;
};

const Foto: React.FC<{ src: string; t: number; a: number; b: number; z0?: number; z1?: number; filter?: string; dx?: number }> = ({ src, t, a, b, z0 = 1.12, z1 = 1.0, filter, dx = 0 }) => {
  const p = interpolate(t, [a, b], [0, 1], cl);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z0 + (z1 - z0) * p}) translateX(${dx * p}px)`, filter }} />
    </AbsoluteFill>
  );
};

// ═════════ cenas ═════════

// 0–2,05 · "Moço, me vê um ferro aí."
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const cam = interpolate(t, [0, 2.1], [1.08, 1], { ...cl, easing: OUT });
  return (
    <AbsoluteFill style={{ background: BG, alignItems: "center", justifyContent: "center" }}>
      <div style={{ transform: `scale(${cam})` }}>
        <Bubble t={t} at={0} who="Cliente">
          <Line t={t} size={84} color={WHITE} hi={CYAN} words={[["Moço,", 0.02], ["me", 0.45], ["vê", 0.56], ["um", 0.7], ["ferro", 0.84, true], ["aí.", 1.2]]} />
        </Bubble>
      </div>
    </AbsoluteFill>
  );
};

// 2,05–6,2 · atendente: "Opa, bom dia! Te ajudo sim. Vai fazer o quê? E sabe a medida?"
const Atende: React.FC<{ t: number }> = ({ t }) => {
  const cam = interpolate(t, [2.0, 6.4], [1, 1.06], cl);
  const sai = k(t, 3.42, 0.3);
  const card = (at: number, icon: React.ReactNode, texto: string) => {
    const p = sp(t, at, 16, 170);
    return (
      <div style={{ width: 840, display: "flex", alignItems: "center", gap: 34, background: WHITE, borderRadius: 40, padding: "40px 48px", boxShadow: "0 24px 60px rgba(14,36,102,0.14)", transform: `translateX(${(1 - p) * 120}px)`, opacity: interpolate(p, [0, 0.3], [0, 1], cl) }}>
        <div style={{ width: 120, height: 120, borderRadius: 30, background: "#E4ECFA", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{icon}</div>
        <div style={{ fontFamily: F, fontWeight: 800, fontSize: 62, color: INK, letterSpacing: -0.5, whiteSpace: "nowrap" }}>{texto}</div>
      </div>
    );
  };
  return (
    <AbsoluteFill style={{ background: BG, alignItems: "center", justifyContent: "center", transform: `scale(${cam})` }}>
      {t < 3.8 && (
        <div style={{ position: "absolute", opacity: 1 - sai, transform: `translateY(${-sai * 80}px)` }}>
          <Bubble t={t} at={2.08} who="Açoron" loja>
            <Line t={t} size={80} words={[["Opa,", 2.1], ["bom", 2.24], ["dia!", 2.4], ["Te", 2.96], ["ajudo", 3.08], ["sim.", 3.3, true]]} />
          </Bubble>
        </div>
      )}
      {t >= 3.45 && (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 44 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, opacity: k(t, 3.45, 0.3), marginBottom: 6 }}>
            <Img src={staticFile("acorou/logo-ar.png")} style={{ width: 70 }} />
            <div style={{ fontFamily: F, fontWeight: 700, fontSize: 32, letterSpacing: 3, color: ROYAL }}>A GENTE PERGUNTA</div>
          </div>
          {card(3.5, <Capacete s={78} />, "Vai fazer o quê?")}
          {card(4.6, <Regua s={78} />, "E sabe a medida?")}
        </div>
      )}
    </AbsoluteFill>
  );
};

// 6,2–8,5 · "Pra obra, ué. Aquele normal."
const Obra: React.FC<{ t: number }> = ({ t }) => {
  const pill = sp(t, 7.16, 13, 190);
  return (
    <AbsoluteFill style={{ background: INK }}>
      <Foto src="acorou/obra.jpg" t={t} a={6.2} b={8.7} z0={1.16} z1={1.04} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(17,26,54,0) 40%, rgba(17,26,54,0.75) 100%)" }} />
      <AbsoluteFill style={{ justifyContent: "flex-end", alignItems: "center", paddingBottom: 300 }}>
        <Bubble t={t} at={6.25} who="Cliente">
          <Line t={t} size={84} color={WHITE} words={[["Pra", 6.3], ["obra,", 6.36], ["ué.", 6.6]]} />
          <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: 22, marginTop: 18 }}>
            <Line t={t} size={84} color={WHITE} words={[["Aquele", 6.75]]} />
            <div style={{ fontFamily: F, fontWeight: 900, fontSize: 84, color: NAVY, background: CYAN, borderRadius: 24, padding: "0 26px 6px", transform: `scale(${pill})`, opacity: interpolate(pill, [0, 0.3], [0, 1], cl) }}>normal</div>
          </div>
        </Bubble>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// 8,5–13,7 · "Então aqui a gente tem: barra, metalom, cantoneira, perfil C, tubo, chapa."
const TEMPOS = [9.36, 9.9, 10.69, 11.53, 12.23, 12.71];
const OFF: number[] = [183, 158, 143, 140, 190, 99]; // centraliza o desenho (a perspectiva joga a peça para a esquerda)
const Tipos: React.FC<{ t: number }> = ({ t }) => {
  let cur = -1;
  TEMPOS.forEach((s, i) => { if (t >= s - 0.08) cur = i; });
  // a fileira de perfis anda como uma prateleira: cada nome traz o seu para o centro
  const pos = TEMPOS.reduce((acc, s, i) => acc + (i === 0 ? 0 : sp(t, s - 0.08, 22, 200)), 0);
  const entra = sp(t, 9.28, 20, 150);
  return (
    <AbsoluteFill style={{ background: `radial-gradient(120% 70% at 50% 45%, #183A94 0%, ${NAVY} 70%)` }}>
      <div style={{ position: "absolute", top: 330, width: "100%" }}>
        <Line t={t} size={64} color={WHITE} hi={CYAN} weight={700} words={[["Então", 8.56], ["aqui", 8.62], ["a", 8.7], ["gente", 8.76], ["tem:", 9.1, true]]} />
      </div>
      {/* seis vagas, que acendem conforme os nomes passam */}
      <div style={{ position: "absolute", top: 470, width: "100%", display: "flex", justifyContent: "center", gap: 14 }}>
        {TEMPOS.map((s, i) => (
          <div key={i} style={{ width: i === cur ? 64 : 22, height: 10, borderRadius: 5, background: i <= cur ? CYAN : "rgba(255,255,255,0.22)", opacity: k(t, 8.9 + i * 0.04, 0.3) }} />
        ))}
      </div>
      {PERFIS.map((p, i) => {
        const x = (i - pos) * 1080 + (1 - entra) * 700;
        if (Math.abs(x) > 1400) return null;
        const rot = -38 + (t - TEMPOS[i]) * 9;
        return (
          <div key={p.nome} style={{ position: "absolute", left: 540 - 320 + x + (OFF[i] ?? 0), top: 680, width: 640, height: 640 }}>
            <Extrude d={p.d} comp={p.comp} size={640} rotY={rot} rotX={i === 5 ? 28 : 16} layers={i === 5 ? 80 : 56} />
          </div>
        );
      })}
      {cur >= 0 && (
        <div key={cur} style={{ position: "absolute", top: 1440, width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
          <div style={{ overflow: "hidden" }}>
            <div style={{ fontFamily: F, fontWeight: 700, fontSize: 44, letterSpacing: 6, color: CYAN, transform: `translateY(${(1 - sp(t, TEMPOS[cur] - 0.08, 20, 220)) * 110}%)` }}>{`0${cur + 1} / 06`}</div>
          </div>
          <div style={{ overflow: "hidden", paddingBottom: 12 }}>
            <div style={{ fontFamily: F, fontWeight: 900, fontSize: 150, color: WHITE, letterSpacing: -2, lineHeight: 1, transform: `translateY(${(1 - sp(t, TEMPOS[cur] - 0.08, 20, 220)) * 110}%)` }}>{PERFIS[cur].nome}</div>
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

// 13,7–20,85 · tamanhos · "Me conta o que vai fazer…" · "Então me dá o do meio."
const TAM = [0.9, 1.2, 1.5];
const Medidas: React.FC<{ t: number }> = ({ t }) => {
  const meio = sp(t, 19.42, 15, 170);
  const swap1 = k(t, 16.0, 0.25);
  const swap2 = k(t, 19.05, 0.25);
  return (
    <AbsoluteFill style={{ background: BG, transform: `scale(${interpolate(t, [13.6, 21], [1.04, 1], cl)})` }}>
      {/* topo: frases que se revezam no mesmo lugar */}
      <AbsoluteFill style={{ alignItems: "center", top: 230, bottom: "auto", height: 520, justifyContent: "flex-start" }}>
        {t < 16.25 && (
          <div style={{ position: "absolute", width: 860, opacity: 1 - swap1 }}>
            <Line t={t} size={92} words={[["Cada", 13.86], ["um", 13.92], ["numa", 14.0], ["grossura", 14.14, true], ["e", 14.7], ["num", 14.77], ["tamanho.", 14.98, true]]} />
          </div>
        )}
        {t >= 16.18 && t < 19.3 && (
          <div style={{ position: "absolute", opacity: 1 - swap2 }}>
            <Bubble t={t} at={16.2} who="Açoron" loja>
              <Line t={t} size={66} words={[["Me", 16.24], ["conta", 16.26], ["o", 16.31], ["que", 16.36], ["vai", 16.6], ["fazer", 16.76, true], ["que", 17.09], ["eu", 17.3], ["te", 17.44], ["mostro", 17.58], ["certo.", 18.37, true]]} />
            </Bubble>
          </div>
        )}
        {t >= 19.25 && (
          <div style={{ position: "absolute" }}>
            <Bubble t={t} at={19.25} who="Cliente">
              <Line t={t} size={76} color={WHITE} hi={CYAN} words={[["Então", 19.3], ["me", 19.32], ["dá", 19.36], ["o", 19.45], ["do", 19.5], ["meio.", 19.6, true]]} />
            </Bubble>
          </div>
        )}
      </AbsoluteFill>
      {/* três metalons de tamanhos diferentes */}
      <div style={{ position: "absolute", top: 880, left: 0, width: 1080, height: 620, display: "flex", alignItems: "flex-end", justifyContent: "center", gap: 16 }}>
        {TAM.map((s, i) => {
          const p = sp(t, 14.1 + i * 0.28, 16, 150);
          const escolhido = i === 1 ? meio : 0;
          const apaga = i !== 1 ? meio * 0.55 : 0;
          return (
            <div key={i} style={{ width: 250 * s, display: "flex", flexDirection: "column", alignItems: "center", transform: `translateY(${(1 - p) * 300 - escolhido * 60}px) scale(${p * (1 + escolhido * 0.08)})`, opacity: 1 - apaga }}>
              <Extrude d={PERFIS[1].d} comp={220 * s} size={250 * s} rotY={-30 + (t - 14) * 4} rotX={18} layers={34} glow={escolhido} />
              <div style={{ marginTop: 34, width: 200 * s, height: 8, borderRadius: 4, background: i === 1 && escolhido > 0.1 ? CYAN : "#B7C3D6" }} />
            </div>
          );
        })}
      </div>
      {/* o "?" do balconista em cima do do meio */}
      <div style={{ position: "absolute", left: 540 - 50, top: 790, width: 100, height: 100, borderRadius: 50, background: CYAN, color: WHITE, fontFamily: F, fontWeight: 900, fontSize: 70, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${sp(t, 19.9, 12, 200)})` }}>?</div>
    </AbsoluteFill>
  );
};

// 20,85–25,5 · "Sem a medida e sem saber pra que vai usar, nem o balcão acerta o material."
// 28,0–29,7 · os mesmos cartões viram certo: "Chega com a medida e o uso…"
const Cartoes: React.FC<{ t: number; ok: boolean; at: [number, number]; escuro: boolean }> = ({ t, ok, at, escuro }) => (
  <div style={{ display: "flex", flexDirection: "column", gap: 34 }}>
    {[["Medida", <Regua key="r" s={80} c={escuro ? WHITE : ROYAL} />], ["Uso", <Capacete key="c" s={80} c={escuro ? WHITE : ROYAL} />]].map(([nome, icon], i) => {
      const p = sp(t, at[i] - 0.1, 16, 160);
      return (
        <div key={i} style={{ width: 820, display: "flex", alignItems: "center", gap: 34, background: escuro ? "rgba(255,255,255,0.08)" : WHITE, border: escuro ? "2px solid rgba(255,255,255,0.14)" : "none", borderRadius: 40, padding: "36px 48px", boxShadow: escuro ? "none" : "0 24px 60px rgba(14,36,102,0.14)", transform: `translateY(${(1 - p) * 80}px)`, opacity: interpolate(p, [0, 0.3], [0, 1], cl) }}>
          <div style={{ width: 120, height: 120, borderRadius: 30, background: escuro ? "rgba(255,255,255,0.1)" : "#E4ECFA", display: "flex", alignItems: "center", justifyContent: "center" }}>{icon}</div>
          <div style={{ flex: 1, fontFamily: F, fontWeight: 800, fontSize: 80, color: escuro ? WHITE : INK }}>{nome as string}</div>
          <Marca p={sp(t, at[i] + 0.15, 12, 200)} ok={ok} />
        </div>
      );
    })}
  </div>
);

const Sem: React.FC<{ t: number }> = ({ t }) => {
  const troca = k(t, 23.1, 0.25);
  return (
